/* Certificat paysage : un étudiant par page, cadre entièrement dans la zone imprimable. */
.certificate{box-sizing:border-box;position:relative;overflow-wrap:anywhere;display:flex;flex-direction:column;justify-content:space-between;min-height:{{ $page_size==='a3'?271:188 }}mm;padding:{{ $page_size==='a3'?9:6 }}mm;border:5px double #267b91;outline:1px solid #bca76c;outline-offset:-8px;font-family:'Times New Roman',serif;font-size:{{ $page_size==='a3'?16:12 }}px;line-height:1.2;background:#fff;margin:0 0 12px;break-inside:avoid}
.certificate:before,.certificate:after{content:'';position:absolute;width:9px;height:9px;border:2px solid #bca76c;background:white;border-radius:50%;top:-4px}.certificate:before{left:-4px}.certificate:after{right:-4px}
.certificate-top{display:flex;align-items:flex-start;justify-content:space-between;gap:3%;text-align:center}.certificate-institution{width:29%;font-size:{{ $page_size==='a3'?12:9 }}px;line-height:1.3;overflow-wrap:anywhere}.certificate-campus,.certificate-tutelle{width:17%;padding-top:5px;display:flex;justify-content:center;gap:5px;align-items:center}.certificate-top img{max-width:100%;height:{{ $page_size==='a3'?135:88 }}px;object-fit:contain}.certificate-tutelle img{max-width:48%;height:{{ $page_size==='a3'?115:78 }}px}.certificate-tutelle img:only-child{max-width:100%}
.certificate-heading{text-align:center;margin:{{ $page_size==='a3'?14:9 }}px 0}.certificate h1{font-size:{{ $page_size==='a3'?27:19 }}px;color:#20576c;margin:0 0 5px;text-transform:uppercase}.certificate h1 small{font-size:65%;white-space:normal}.certificate-english{font-size:{{ $page_size==='a3'?20:14 }}px;font-weight:bold;font-style:italic}
.certificate-content p{margin:{{ $page_size==='a3'?9:5 }}px 0;text-align:justify}.certificate-content em,.certificate-signatures em,.certificate-issued em{font-size:88%}.certificate-certification{text-indent:3em}.certificate-identity,.certificate-results{display:flex;justify-content:space-between;gap:15px}.certificate-identity{margin:8px 0 6px 12%}.certificate-identity strong{font-size:115%}.certificate-identity>div{max-width:62%}.certificate-birth{margin-left:12%}.certificate-birth span{display:inline-block;margin-left:8%}.certificate-results{text-align:center}.certificate-issued{text-align:center;margin-top:6px}.certificate-signatures{display:flex;justify-content:space-between;text-align:center;margin-top:6px;gap:25px}.certificate-signatures>div{width:45%}.certificate-signature-space{height:{{ $page_size==='a3'?28:15 }}mm}
.certificate-bottom{text-align:center;font-size:{{ $page_size==='a3'?11:8 }}px}.certificate-bottom p{margin:3px 0}.certificate-bottom .certificate-legal{font-size:85%}.certificate .document-footer{font-family:Arial,sans-serif;margin-top:4px;padding-top:3px;font-size:{{ $page_size==='a3'?9:6 }}px}
@media print{body.document-attestation{padding:0!important}.document-attestation .preview{display:none}.certificate{height:{{ $page_size==='a3'?271:188 }}mm;margin:0;min-height:0}.certificate .document-footer{display:block}.certificate:last-of-type{break-after:auto;page-break-after:auto}}
/* Ngaoundéré : campus à gauche, université au centre, IUT à droite. */
.modele-ngaoundere .certificate{border-color:#28638b;outline-color:#aeb9c0;font-size:{{ $page_size==='a3'?15:11 }}px}
.certificate-ngaoundere-top{gap:1%}.certificate-ngaoundere-top .certificate-institution{width:28%;font-size:{{ $page_size==='a3'?11:8 }}px}.certificate-ngaoundere-top .certificate-campus,.certificate-university,.certificate-iut{width:13%;text-align:center;padding-top:5px}.certificate-ngaoundere-top img{height:{{ $page_size==='a3'?96:65 }}px;max-width:100%;object-fit:contain}
.modele-ngaoundere .certificate h1{font-size:{{ $page_size==='a3'?24:17 }}px}.modele-ngaoundere .certificate-heading{margin:6px 0}.modele-ngaoundere .certificate-content p{margin:{{ $page_size==='a3'?6:4 }}px 0}.modele-ngaoundere .certificate-conventions{font-size:94%;line-height:1.15}.modele-ngaoundere .certificate-certification{text-indent:0}.modele-ngaoundere .certificate-signature-space{height:{{ $page_size==='a3'?23:13 }}mm}
/* Polytechnique : modèle SOA avec ENSPY au centre et université à droite. */
.certificate-polytechnique-top{gap:1%}.certificate-polytechnique-top .certificate-institution{width:28%}.certificate-polytechnique-top .certificate-campus,.certificate-polytechnique-top .certificate-tutelle,.certificate-polytechnique{width:13%;padding-top:5px;text-align:center}.certificate-polytechnique-top .certificate-tutelle{justify-content:center}.certificate-polytechnique img{max-width:100%;object-fit:contain}
